// THE dynamic canonical output contract for Admin Bulk Upload prompts.
//
// SINGLE SOURCE OF TRUTH (Phases 3, 4, 8):
//   Every Admin Bulk Upload prompt — DB-stored, in-code fallback, or the 
//   "Copy System Prompt" shortcut — is composed at display/copy time from a
//   topic prompt plus THIS contract. The contract is generated by the
//   application, versioned via QUESTION_OUTPUT_CONTRACT_VERSION, and never
//   stored inside topic prompts (their format sections hold the marker
//   [PREPAREFORU_DYNAMIC_OUTPUT_CONTRACT] instead).
//
// The contract stays in lock-step with the PRODUCTION parsers:
//   - The visual type enum is imported from src/types/exam.types
//     (SUPPORTED_VISUAL_TYPES) — the same enum the parser switches on.
//   - The size limits are imported from questionVisualSchemas.ts
//     (VISUAL_LIMITS) — the same limits assertVisualSizeLimits enforces.
//   - Every example object built by buildVisualExample / 
//     buildCanonicalQuestionExample is asserted in unit tests to pass the REAL
//     normalizeVisualInput → BulkQuestionSchema → SingleQuestionSchema write
//     chain. If the prompt teaches a shape the parser rejects, tests fail.
//
// The contract deliberately contains NO legacy tokens: no visual_engine, no
// render_type, no bilingual visual keys (title_en/title_te/headers_en/rows_en),
// no separate language-specific visual siblings, no `options`/`correct`
// aliases, no `metadata` wrapper, no `diagram` forms, and no unsupported types.
// Every visual is ONE canonical object whose human-readable text is bilingual
// ("English / Telugu") per the VISUAL LANGUAGE RULE taught below. Tests scan
// BOTH the contract and every FINAL composed prompt (topic body + identity +
// contract) for these tokens.

import { SUPPORTED_VISUAL_TYPES } from '../../types/exam.types'
import type { VisualType } from '../../types/exam.types'
import { VISUAL_LIMITS } from '../../validations/questionVisualSchemas'
import type { CanonicalQuestionVisual } from '../../validations/questionVisualSchemas'

export const QUESTION_OUTPUT_CONTRACT_VERSION = '1.5'

/** Header that makes composeBulkUploadPrompt idempotent (contract present). */
export const CONTRACT_AUTHORITY_PREFIX = 'CANONICAL OUTPUT CONTRACT'
export const CONTRACT_IDEMPOTENCY_RE = new RegExp(`${CONTRACT_AUTHORITY_PREFIX} v\\d+\\.\\d+`)

const VERSION = QUESTION_OUTPUT_CONTRACT_VERSION

// ─────────────────────────────────────────────────────────────────────────────
// Single structure for the canonical question object the AI must emit. The key
// order and naming is exactly what BulkQuestionSchema consumes after normal-
// ization; the Telugu/topic bytes pass through untouched.
// ─────────────────────────────────────────────────────────────────────────────

export const CANONICAL_QUESTION_FIELDS: readonly string[] = [
  '"topic_en" — copy VERBATIM from this prompt (never translate); identifies the Topic GROUP, never a subtopic',
  '"topic_te" — copy VERBATIM from this prompt; null only when the topic has no Telugu',
  '"question_text_en" — the English question',
  '"question_text_te" — Telugu question (REQUIRED when this topic has a Telugu name; null only when the topic has no Telugu)',
  '"option_a_en" / "option_b_en" / "option_c_en" / "option_d_en" — exactly 4 English options, each the BARE answer text with NO "A. " / "B. " / "C. " / "D. " letter prefix (the letter identity is the key suffix)',
  '"option_a_te" / "option_b_te" / "option_c_te" / "option_d_te" — Telugu options (REQUIRED when this topic has a Telugu name); likewise BARE answer text with NO "ఎ. " / "బి. " / "సి. " / "డి. " letter prefix',
  '"correct_option" — the bare uppercase letter "A", "B", "C" or "D": NEVER "B. Canberra", never "Canberra", and never the Telugu letters ఎ./బి./సి./డి.',
  '"explanation_en" — brief explanation why the answer is correct',
  '"explanation_te" — Telugu explanation (REQUIRED when this topic has a Telugu name)',
  '"difficulty" — exactly one of "easy", "medium", "hard"',
  '"visual" — null, or the visual object described in the CANONICAL VISUAL REQUIREMENTS below (include only when the candidate must reason from it)',
]

// ─────────────────────────────────────────────────────────────────────────────
// Visual contract — one spec record per supported type. The prose description
// and the machine-checked example are generated from the SAME record, so the
// prompt can never teach a shape the parser rejects.
// ─────────────────────────────────────────────────────────────────────────────

export interface VisualTypeContract {
  type: VisualType
  dataFields: string
  buildData: () => Record<string, unknown>
}

const TITLE_PATTERN = `"title": "short heading" or null (max ${VISUAL_LIMITS.maxTitleLength} characters)`

// Every example is deliberately BILINGUAL: the ONE canonical visual carries all
// human-readable text as "English / Telugu" (single string, space-slash-space).
// A visual is never duplicated into language-specific siblings. Numbers and
// coordinates stay numeric; Mermaid/SVG/LaTeX syntax and JSON keys are unchanged.
// The table, geometry, svg, and map_overlay examples keep numerical/structural
// values numeric while splitting only language-bearing text; the latex example
// keeps the formula pure (its bilingual text lives in the title).
const BILINGUAL_EXAMPLE_TITLES: Record<VisualType, string> = {
  table: 'Major Rivers / ప్రధాన నదులు',
  chart: 'Crop Production / పంట ఉత్పత్తి',
  geometry: 'Triangle / త్రిభుజం',
  venn: 'Classification / వర్గీకరణ',
  mermaid: 'Parliament Structure / పార్లమెంటు నిర్మాణం',
  latex: 'Quadratic Formula / ద్విఘాత సూత్రం',
  svg: 'River Course / నది మార్గం',
  map_overlay: 'Empire Extent / సామ్రాజ్య విస్తీర్ణం',
}

