/** Compose the full canonical output contract block appended to topic prompts.
 *  Module-level memoized: the contract describes static system data. */
let cachedContract: string | null = null
export function buildCanonicalOutputContract(): string {
  if (cachedContract !== null) return cachedContract
  const contract = [
    '======================================================================',
    `${CONTRACT_AUTHORITY_PREFIX} v${VERSION} \u2014 AUTHORITY`,
    '======================================================================',
    '',
    'The topic instructions above define WHAT to generate. This section is the ONLY',
    'authority for HOW the output must be shaped. If the topic instructions above',
    'embed any other JSON schema, alias names, or visual shape, IGNORE that guidance:',
    'the keys, enums, and visual shapes in THIS section are the only ones accepted',
    'by the uploader.',
    buildQuestionSection(),
    buildBilingualSection(),
    buildOptionSection(),
    buildDistributionSection(),
    buildVisualSection(),
    buildGoodBadExamplesSection(),
    buildAnswerLeakSection(),
    buildSelfVerificationSection(),
  ].join('\n')
  cachedContract = contract
  return contract
}

export interface ComposedContractInfo {
  text: string
  version: string
  visualTypes: readonly string[]
}

export function describeCanonicalOutputContract(): ComposedContractInfo {
  return {
    text: buildCanonicalOutputContract(),
    version: VERSION,
    visualTypes: SUPPORTED_VISUAL_TYPES,
  }
}